import { z } from 'zod';

/** PHI fields are encrypted before storage and never logged. */
export const PHI_FIELDS = ['name', 'dob', 'mrn', 'phone', 'address', 'insuranceId'] as const;

export const IntakeSchema = z.object({
  name: z.string().min(1).max(120),
  dob: z.string().regex(/^\d{4}-\d{2}-\d{2}$/),
  mrn: z.string().max(32).optional(),
  phone: z.string().max(20),
  address: z.string().max(240),
  insuranceId: z.string().max(40).optional(),
  consent: z.literal(true),
  reasonForVisit: z.string().max(500),
}).strict();

export type Intake = z.infer<typeof IntakeSchema>;

import { IntakeSchema, PHI_FIELDS } from './schema';
import { sealFields } from '../../crypto/field_seal';
import { audit } from '../../audit/log';
import { db } from '../../db';

export async function createIntake(req: AuthedRequest): Promise<Response> {
  const parsed = IntakeSchema.safeParse(await req.json());
  if (!parsed.success) {
    audit({ actor: req.user.id, action: 'intake.reject', target: 'intake', detail: parsed.error.issues.map((i) => i.path.join('.')) });
    return Response.json({ error: 'invalid intake' }, { status: 422 });
  }
  const sealed = await sealFields(parsed.data, PHI_FIELDS);
  const { id } = await db.intake.insert(sealed);
  audit({ actor: req.user.id, action: 'intake.create', target: `patient:${id}` });
  return Response.json({ id }, { status: 201 });
}

