let prev = 'genesis';
/** Append-only, hash-chained: each record commits to the one before it (164.312(c) integrity). */
export function audit(e: Omit<AuditEvent, 'at'> & { detail?: unknown }): void {
  const record = { ...e, at: new Date().toISOString(), prev };
  const hash = sha256(JSON.stringify(record));
  appendFileSync(AUDIT_FILE, JSON.stringify({ ...record, hash }) + '\n', { mode: 0o600 });
  prev = hash;
}

