import { describe, expect, test } from 'bun:test';
import { app, asClinician, readAuditLog } from '../helpers';

describe('POST /v1/intake', () => {
  test('rejects unknown fields', async () => {
    const res = await asClinician(app).post('/v1/intake', { ...valid, ssn: '000-00-0000' });
    expect(res.status).toBe(422);
  });
  test('never writes PHI to the audit log', async () => {
    await asClinician(app).post('/v1/intake', valid);
    expect(readAuditLog()).not.toContain(valid.name);
  });
  test('audit chain verifies', async () => {
    expect(await verifyChain()).toEqual({ ok: true });
  });
});
